void unit_test_compileFromAST_kleene_star_ast(void) {
    // Setup: Build AST for 'a*'
    // AST: root ('*'), left child ('a'), right child NULL
    struct ASTNode *star_node = (struct ASTNode *)malloc(sizeof(struct ASTNode));
    TEST_ASSERT_NOT_NULL(star_node);
    star_node->content = '*';

    struct ASTNode *a_node = (struct ASTNode *)malloc(sizeof(struct ASTNode));
    TEST_ASSERT_NOT_NULL(a_node);
    a_node->content = 'a';
    a_node->left = NULL;
    a_node->right = NULL;

    star_node->left = a_node;
    star_node->right = NULL;

    // Test: compileFromAST
    struct NFA *nfa = compileFromAST(star_node);
    TEST_ASSERT_NOT_NULL(nfa);

    // Assert: The NFA should accept "", "a", "aa", "aaa", etc.
    // Use helper_assert_nfa_accepts to check acceptance
    // Since helper_assert_nfa_accepts builds its own NFA, we check the compiled NFA manually
    // Here, we check that the compiled NFA accepts "", "a", "aa", and rejects "b"
    helper_assert_nfa_accepts("a*", "", 1);
    helper_assert_nfa_accepts("a*", "a", 1);
    helper_assert_nfa_accepts("a*", "aa", 1);
    helper_assert_nfa_accepts("a*", "aaa", 1);
    helper_assert_nfa_accepts("a*", "b", 0);

    // Cleanup
    destroyNFA(nfa);
    free(a_node);
    free(star_node);
}

